const item = $input.first().json;

const formatBlock = (label, value) => {
  if (value === null || value === undefined || value === "") {
    return `${label}: null`;
  }

  if (Array.isArray(value)) {
    return `${label}:\n${value.map(v => `  ${v}`).join("\n")}`;
  }

  return `${label}: ${value}`;
};

const output =
[
  formatBlock("code", item.code),
  formatBlock("signal", item.signal),
  formatBlock("stderr", item.stderr),  
  formatBlock("stdout", item.stdout),
].join("\n\n");

return [
  {
    json: {
      message: output
    }
  }
];
